import path from 'path';
import { z } from 'zod/v3';
import { explorationShape } from './explorationSchema';
import {
  registerIntentTool,
  requiredText,
  localRead,
  localChange,
  externalChange,
  optionArgs,
  type IntentToolDependencies,
} from './intentTool';
import { callerModelArgsFromToolMeta } from '../cli/callerModel';
import { getExploration } from './getExploration';

export const registerExplorationTools = (
  dependencies: IntentToolDependencies,
): void => {
  const { runCommand, projectArgs } = dependencies;
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_explore_designs',
      title: 'Explore design directions',
      description:
        'Explore designs or vary a selected direction. Requires a short batch runLabel and one authored brief per direction. Resolves selected saved instructions and references, persists isolated workspaces, and starts workers that can run local commands and contact model services. This consumes the selected provider usage. Supply workerProvider/model only on explicit user request. Does not apply a result. When nextAction is present, follow its workerPrompt and parallelism exactly; otherwise read rivet_get_exploration until settled. editor.open is an inert CLI handoff to the project comparison workspace. Never cancel to unblock a start.',
      shape: explorationShape,
      annotations: externalChange,
    },
    async (input, extra) =>
      runCommand(
        'variants',
        [
          'start',
          ...projectArgs(path.resolve(input.project)),
          ...optionArgs('--instruction', input.instruction),
          ...optionArgs('--run-label', input.runLabel),
          ...optionArgs('--briefs', input.briefs),
          ...optionArgs('--element', input.element),
          ...optionArgs('--files', input.files),
          ...(input.fresh ? ['--fresh'] : []),
          ...optionArgs('--profile', input.profile),
          ...optionArgs('--guidance', input.guidance),
          ...optionArgs('--exclude-guidance', input.excludedGuidanceIds),
          ...optionArgs('--fidelity', input.fidelity),
          ...optionArgs('--worker-provider', input.workerProvider),
          ...optionArgs('--worker-model', input.workerModel),
          ...optionArgs('--context-images', input.contextImages),
          ...optionArgs('--context-assets', input.contextAssets),
          ...optionArgs('--reference-pages', input.referencePages),
          ...optionArgs('--reference-videos', input.referenceVideos),
          ...optionArgs('--reference-picks', input.referencePicks),
          ...optionArgs('--target', input.baseDirectionId),
        ],
        { handoffArgs: callerModelArgsFromToolMeta(extra._meta) },
      ),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_get_exploration',
      title: 'Inspect design exploration',
      description:
        'Read live progress, saved results and preview locations for a project, optionally one session/direction. With workId, includes recorded instruction and reference receipts for that request, never recomputed suggestions. Receipt selected/images describe this request; inheritedReferences lists references retained from a Vary source. Returns an inert editor.open CLI handoff to the project comparison workspace. Does not start servers, authorize a browser, resume imports, apply designs or run checks. Missing receipts are reported as unavailable. Poll while work is running; follow returned host-work nextAction when present.',
      shape: {
        project: requiredText,
        sessionId: requiredText.optional(),
        variantId: requiredText.optional(),
        workId: requiredText.optional(),
        includeHistory: z.boolean().optional(),
      },
      annotations: localRead,
    },
    async (input, extra) =>
      getExploration({
        ...input,
        callerAgent: dependencies.callerAgent,
        callerModel: callerModelArgsFromToolMeta(extra._meta)[1],
      }),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_cancel_exploration',
      title: 'Cancel exploration',
      description:
        'Cancel the explicitly named exploration and stop its in-progress work. Requires a user request to cancel. Never use cancellation to unblock another generation or to refresh status.',
      shape: { project: requiredText, sessionId: requiredText },
      annotations: localChange,
    },
    async (input) =>
      runCommand('variants', [
        'cancel',
        input.sessionId,
        ...projectArgs(input.project),
      ]),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_complete_variant_work',
      title: 'Report assigned worker completion',
      description:
        'For the host-worker fallback only: report one assigned work item completed, failed or cancelled after following its workerPrompt. Rivet reads artifacts from the assigned workspace and may run quality checks or queue regeneration. acceptedStatus and stage describe authoring. result.variant contains the current direction snapshot, or null when unavailable. Its preview, previewUnavailable and actions.view report existing preview evidence, not browser verification. Missing preview and failure evidence means availability is unknown. editor.open is an inert CLI handoff to the project comparison workspace. Do not pass inline HTML or wait for sibling workers. This does not apply a direction to the user project.',
      shape: {
        project: requiredText,
        sessionId: requiredText,
        workId: requiredText,
        status: z.enum(['succeeded', 'failed', 'cancelled']),
        output: z.unknown().optional(),
        error: requiredText.optional(),
        title: requiredText.optional(),
        description: requiredText.optional(),
      },
      annotations: externalChange,
    },
    async (input) =>
      runCommand('variants', [
        'complete',
        input.workId,
        '--session',
        input.sessionId,
        '--status',
        input.status,
        ...optionArgs('--output', input.output),
        ...optionArgs('--error', input.error),
        ...optionArgs('--title', input.title),
        ...optionArgs('--description', input.description),
        ...projectArgs(input.project),
      ]),
  );
};
